# V23-D10: generations up to 22 wrote requiredCoverage=satisfied, deficiency=none and a SUCCESS
# termination for every Run, although every retained Run is sealed `indeterminate` with a
# required-execution deficiency in its proof. The whole-Run projection is now derived from the
# admitted proof through the owners below (generation-22 bytes: predecessors.v22/envelopes).
D9_CONTRACT = 'docs/coop/artifacts/d9-exit-contract.v1.14.json'
# native-evidence.md section 10 precedence, most specific first
NATIVE_PRECEDENCE = ['language-tier-unsupported', 'provider-unavailable', 'input-closure-incomplete',
                     'budget-exhausted', 'confidence-floor-unmet', 'derivation-policy-unmet',
                     'resolution-incomplete', 'external-consumers-unknown',
                     'required-relation-missing']
# proof cause -> D9Deficiency. required-cell-unsatisfied is composition section 9.6's null
# DeficiencyV2 route ("pure missing work"), i.e. required Coverage missing (I-D1).
D9_OF_PROOF_CAUSE = {'required-cell-unsatisfied': 'required-relation-missing',
                     'required-relation-missing': 'required-relation-missing',
                     'language-tier-unsupported': 'language-tier-unsupported',
                     'provider-unavailable': 'provider-unavailable',
                     'budget-exhausted': 'budget-exhausted',
                     'confidence-floor-unmet': 'confidence-floor-unmet'}
SCENARIO_OF = {'required-relation-missing': 'analysis-required-coverage-missing',
               'language-tier-unsupported': 'analysis-language-tier-unsupported',
               'provider-unavailable': 'analysis-required-provider-unavailable',
               'budget-exhausted': 'analysis-budget-exhausted',
               'confidence-floor-unmet': 'analysis-confidence-floor-unmet',
               'verdict-indeterminate': 'analysis-verdict-indeterminate',
               'none:pass': 'analysis-pass', 'none:advisory': 'analysis-advisory',
               'none:fail': 'analysis-policy-fail'}


def d9_scenarios():
    out = {}

    def walk(n):
        if isinstance(n, dict):
            if 'scenarioAxes' in n and 'expectedTermination' in n:
                out[n['id']] = n
            for v in n.values():
                walk(v)
        elif isinstance(n, list):
            for v in n:
                walk(v)
    walk(kitdoc(D9_CONTRACT))
    return out


def d9_projection(rf):
    """AnalysisResult requiredCoverage/deficiency/secondaryDeficiencies and the step termination,
    derived from proof.executionDeficiencies and the sealed verdict."""
    sc_all = d9_scenarios()
    d9 = []
    for d in rf['executionDeficiencies']:
        m = D9_OF_PROOF_CAUSE[d['cause']]
        if m not in d9:
            d9.append(m)
    d9.sort(key=NATIVE_PRECEDENCE.index)
    if d9:
        primary, secondary = d9[0], d9[1:]
    elif rf['verdict'] == 'indeterminate':
        primary, secondary = 'verdict-indeterminate', []
    else:
        primary, secondary = 'none', []
    sc = sc_all[SCENARIO_OF[primary if primary != 'none' else 'none:' + rf['verdict']]]
    axes, want = sc['scenarioAxes'], sc['expectedTermination']
    assert axes['verdict'] == rf['verdict'], (sc['id'], rf['verdict'])
    term = {'class': want['class']}
    reasons = list(want.get('reasonCodes') or [])
    for s in secondary:
        reasons += [c for c in sc_all[SCENARIO_OF[s]]['expectedTermination'].get('reasonCodes') or []
                    if c not in reasons]
    if reasons:
        term['reasonCodes'] = reasons
    if want.get('runId') == '$RUN_ID':
        term['runId'] = rf['runId']
    cited = None
    if 'coverageId' in want:
        for d in rf['executionDeficiencies']:
            if D9_OF_PROOF_CAUSE[d['cause']] == primary:
                covs = [r['digest'] for r in d['inputRefs'] if r['domain'] == 'coverage']
                if covs:
                    cited = 'coverage2:' + covs[0]
                    break
        if cited:
            term['coverageId'] = cited
    return {'requiredCoverage': axes['requiredCoverage'], 'deficiency': primary,
            'secondaryDeficiencies': secondary, 'termination': term,
            'derivation': {'d9Scenario': sc['id'], 'proofCauses': [d['cause'] for d in
                                                                   rf['executionDeficiencies']],
                           'coverageIdCited': cited,
                           'coverageIdStanding': (None if cited or 'coverageId' not in want else
                                                  'no deficiency row of the primary cause cites a '
                                                  'Coverage record, so none is named')}}


def analysis_result(rf, *, authoritative=True):
    p = d9_projection(rf)
    if authoritative:
        return {'kind': 'analysis', 'authority': 'authoritative', 'runId': rf['runId'],
                'planId': rf['planId'], 'verdict': rf['verdict'],
                'requiredCoverage': p['requiredCoverage'], 'durability': 'committed',
                'deficiency': p['deficiency'],
                'secondaryDeficiencies': p['secondaryDeficiencies']}
    return {'kind': 'analysis', 'authority': 'ephemeral', 'planId': rf['planId'],
            'evidenceId': rf['evidenceId'], 'verdict': rf['verdict'],
            'requiredCoverage': p['requiredCoverage'], 'durability': 'not-required',
            'deficiency': p['deficiency'], 'secondaryDeficiencies': p['secondaryDeficiencies']}

