@handler('R-PUBLIC-TERMINATION-EXAMPLES', 'reconstructed-behavior', ['envelopes/public-termination.json'],
         'V23-D11: six class examples re-admitted, each compared field by field with the kit golden it '
         'cites; no example asserts a verdict for a retained Run, synthetic identities are labelled')
def _():
    v = J('envelopes/public-termination.json')
    gold = {g['id']: g for g in kitjson('workflows/command-inventory.v3.json')['goldens']}
    current = set(current_run_ids().values())
    for e in v['envelopes']:
        env, lab = e['envelope'], e['label']
        envelope_check(env, lab)
        g = gold.get((e.get('golden') or {}).get('id'))
        if not A.need(g is not None, 'EXAMPLE_CITES_A_KIT_GOLDEN:' + lab):
            continue
        t = env['termination']
        A.need(t['class'] == g['class'] and env['exitCode'] == g['exitCode'], 'CLASS_AND_EXIT_ARE_THE_GOLDEN:' + lab,
               {'emitted': (t['class'], env['exitCode']), 'golden': (g['class'], g['exitCode'])})
        if g.get('errorCode'):
            A.need(t.get('errorCode') == g['errorCode'], 'ERROR_CODE_IS_THE_GOLDEN:' + lab)
        if g.get('reasonCode'):
            A.need(t.get('reasonCodes') == [g['reasonCode']], 'REASON_CODE_IS_THE_GOLDEN:' + lab)
        if g.get('domainDetail'):
            A.need((t.get('domainDetail') or {}).get('code') == g['domainDetail'], 'DOMAIN_DETAIL_IS_THE_GOLDEN:' + lab)
        refs = set()
        walk(env, lambda n, p: refs.add(n) if isinstance(n, str) and n.startswith('run3:') else None)
        A.need(not refs & current, 'NO_EXAMPLE_ASSERTS_A_VERDICT_FOR_A_RETAINED_RUN:' + lab, sorted(refs & current))
        A.need(not refs or e.get('syntheticHelperOnly'), 'SYNTHETIC_RUN_IDENTITIES_ARE_LABELLED:' + lab)
        if env.get('run'):
            A.need(env['run']['verdict'] == {'success': 'pass', 'policy-failed': 'fail'}.get(t['class']),
                   'RUN_VERDICT_AGREES_WITH_THE_TERMINATION_CLASS:' + lab)
    A.need({e['envelope']['termination']['class'] for e in v['envelopes']} == set(exit_table()), 'EVERY_KIT_D9_CLASS_EXEMPLIFIED')

